import test from 'node:test';
import assert from 'node:assert/strict';
import { recordPayment, balanceDue } from '../src/payments.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';

test('recordPayment adds a payment to an issued invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = invoiceResult.value;
  const issuedResult = issueInvoice(invoice, []);
  const issuedInvoice = issuedResult.value;

  const r = recordPayment(issuedInvoice, { amount: 50000, date: '2026-10-10' });
  assert.equal(r.ok, true);
